252	/** Splits a raw request target at the first `?`, with no decoding or normalisation. */
253	function splitTarget(target) {
254	  const mark = target.indexOf('?');
255	  if (mark === -1) return { path: target, query: '' };
256	  return { path: target.slice(0, mark), query: target.slice(mark + 1) };
257	}
258	
259	function isKnownPath(path) {
260	  return path === '/api/rooms' || path === BOOKINGS_PATH || isBookingItemPath(path) || Object.hasOwn(PAGE_FILES, path);
261	}
262	
263	/**
264	 * CONNECT never reaches the request listener, so it is answered here on the raw socket:
265	 * 405 on a known path, 404 otherwise. Any data after the headers is discarded.
266	 */
267	function answerConnect(req, socket) {
268	  socket.on('error', (error) => process.stderr.write(`connect socket error: ${error.code ?? 'unknown'}\n`));
269	  const known = isKnownPath(splitTarget(req.url).path);
270	  const [status, reason, message] = known ? [405, 'Method Not Allowed', MSG.method] : [404, 'Not Found', MSG.notFound];
271	  const body = JSON.stringify({ error: message });
272	  socket.end(
273	    `HTTP/1.1 ${status} ${reason}\r\nContent-Type: ${JSON_TYPE}\r\n` +
274	      `Content-Length: ${Buffer.byteLength(body)}\r\nConnection: close\r\n\r\n${body}`,
275	  );
276	}
277	
278	/** Picks the handler for a request; returns a function producing the reply. */
279	function route(handlers, req, res, body) {
280	  const target = req.url;
281	  const { path, query } = splitTarget(target);
282	  const { method } = req;
283	  const only = (allowed, run) => () => (method === allowed ? run() : sendError(res, 405, MSG.method));
284	
285	  if (path === '/api/rooms') return only('GET', () => sendJson(res, 200, { rooms: ROOMS }));
286	  if (path === BOOKINGS_PATH) {
287	    if (method === 'POST') return () => handlers.createBooking(req, res, body);
288	    return only('GET', () => handlers.listBookings(res, query));
289	  }
290	  if (isBookingItemPath(path)) {
291	    return only('DELETE', () => handlers.deleteBooking(res, path.slice(BOOKING_ITEM_PREFIX.length)));
292	  }
293	  if (Object.hasOwn(PAGE_FILES, path)) return only('GET', () => handlers.servePage(res, PAGE_FILES[path]));
294	  return () => sendError(res, 404, MSG.notFound);
295	}
296	
297	// ---------- server ----------
298	
299	/** Runs tasks one at a time, in arrival order. */
300	function createQueue() {
301	  let tail = Promise.resolve();
302	  return (task) => {
303	    const run = tail.then(task);
304	    // The caller handles run's failure; the tail only needs to settle so the next task can start.
305	    tail = run.then(() => undefined, () => undefined);
306	    return run;
307	  };
308	}
309	
310	function createStore(path, initial) {
311	  let state = initial;
312	  return {
313	    get: () => state,
314	    async commit(next) {
315	      await saveState(path, next);
316	      state = next;
317	    },
318	  };
319	}
320	
321	function createRequestListener(store) {
322	  const handlers = createHandlers(store);
323	  const enqueue = createQueue();
324	  return async (req, res) => {
325	    let body;
326	    try {
327	      body = await readBody(req);
328	    } catch {
329	      req.destroy();
330	      return;
331	    }
332	    try {
333	      await enqueue(() => route(handlers, req, res, body)());
334	    } catch (error) {
335	      process.stderr.write(`internal error: ${error?.code ?? error?.name ?? 'unknown'}\n`);
336	      if (!res.headersSent) sendError(res, 500, MSG.internal);
337	      else res.destroy();
338	    }
339	  };
340	}
341	
342	function parsePort(raw) {
343	  if (raw === undefined || raw === '') return DEFAULT_PORT;
344	  if (!/^[0-9]+$/.test(raw)) return null;
345	  const port = Number(raw);
346	  return port <= MAX_PORT ? port : null;
347	}
348	
349	function fail(message) {
350	  process.stderr.write(`${message}\n`);
351	  process.exitCode = 1;
352	}
353	
354	function main() {
355	  const port = parsePort(process.env.PORT);
356	  if (port === null) return fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
357	  const dataName = process.env.DATA_FILE || 'bookings.json';
358	  const dataPath = resolve(process.cwd(), dataName);
359	  const initial = loadState(dataPath);
360	  if (initial === null) return fail(`cannot read data file ${dataName}`);
361	
362	  const listener = createRequestListener(createStore(dataPath, initial));
363	  const server = createServer(listener);
364	  // Unknown Expect values go to the normal route instead of Node's automatic 417.
365	  server.on('checkExpectation', listener);
366	  server.on('connect', answerConnect);
367	  const onBindError = (error) => fail(`cannot listen on port ${port}: ${error.code ?? 'unknown error'}`);
368	  server.once('error', onBindError);
369	  server.listen(port, HOST, () => {
370	    server.off('error', onBindError);
371	    server.on('error', (error) => process.stderr.write(`server error: ${error.code ?? 'unknown'}\n`));
372	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
373	  });
374	  return undefined;
375	}
376	
377	main();
378

