2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Room bookings</title>
7	<style>
8	  :root {
9	    --ink: #1d232b;
10	    --muted: #5b6573;
11	    --paper: #f6f4ef;
12	    --card: #ffffff;
13	    --line: #d9d4c9;
14	    --accent: #2f5d50;
15	    --danger: #a3302a;
16	    font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
17	    color: var(--ink);
18	    background: var(--paper);
19	  }
20	  body { max-width: 44rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
21	  h1 { font-size: 2rem; letter-spacing: -0.01em; margin: 0 0 1.5rem; border-bottom: 2px solid var(--ink); padding-bottom: 0.5rem; }
22	  h2 { font-size: 1.1rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin: 2rem 0 0.75rem; }
23	  form, .filter { background: var(--card); border: 1px solid var(--line); border-radius: 6px; padding: 1rem; }
24	  form { display: grid; grid-template-columns: max-content 1fr; gap: 0.6rem 1rem; align-items: center; }
25	  .filter { display: flex; flex-wrap: wrap; gap: 0.6rem 1rem; align-items: center; }
26	  label { font-weight: 600; }
27	  input, select, button { font: inherit; font-size: 1rem; padding: 0.4rem 0.6rem; border: 1px solid var(--line); border-radius: 4px; background: #fff; color: var(--ink); }
28	  input:focus-visible, select:focus-visible, button:focus-visible { outline: 3px solid var(--accent); outline-offset: 1px; }
29	  button { cursor: pointer; }
30	  button[type="submit"] { grid-column: 2; justify-self: start; background: var(--accent); color: #fff; border-color: var(--accent); }
31	  button:disabled { opacity: 0.55; cursor: progress; }
32	  #booking-list { list-style: none; padding: 0; margin: 1rem 0 0; }
33	  #booking-list li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 0.6rem 0; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; }
34	  #error { color: var(--danger); font-weight: 600; min-height: 1.5em; }
35	</style>
