import { spawn } from 'node:child_process';
import net from 'node:net';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const sol = path.resolve(process.argv[2]);
const results = [];
function check(name, cond, info) { results.push(`${cond ? 'PASS' : 'FAIL'} ${name}${cond ? '' : ' :: ' + JSON.stringify(info)}`); }

function run(env, cwd) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [path.join(sol, 'server.mjs')], { env: { PATH: process.env.PATH, ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    const t = setTimeout(() => resolve({ p, out, err, code: null, running: true }), 1500);
    p.on('exit', (code) => { clearTimeout(t); resolve({ out, err, code, running: false }); });
    p.stdout.on('data', () => { if (/listening on http:\/\/127\.0\.0\.1:\d+\n/.test(out)) { clearTimeout(t); resolve({ p, out, err, code: null, running: true }); } });
  });
}

function raw(port, data) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1');
    let buf = '';
    s.on('data', (d) => { buf += d; });
    s.on('end', () => resolve(buf));
    s.on('error', () => resolve(buf));
    s.write(data);
    setTimeout(() => { s.destroy(); resolve(buf); }, 1500);
  });
}
function parse(r) {
  const i = r.indexOf('\r\n\r\n');
  const head = r.slice(0, i); const body = r.slice(i + 4);
  const status = Number(head.split(' ')[1]);
  let json; try { json = JSON.parse(body); } catch {}
  return { status, head, body, json };
}
async function req(port, method, target, { headers = {}, body } = {}) {
  let h = `${method} ${target} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n`;
  for (const [k, v] of Object.entries(headers)) h += `${k}: ${v}\r\n`;
  const b = body === undefined ? Buffer.alloc(0) : Buffer.isBuffer(body) ? body : Buffer.from(body);
  if (body !== undefined) h += `Content-Length: ${b.length}\r\n`;
  return parse(await raw(port, Buffer.concat([Buffer.from(h + '\r\n'), b])));
}
const J = { 'Content-Type': 'application/json' };
const bk = (o) => JSON.stringify({ room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'probe-'));

// startup
for (const [P, ok] of [['abc', false], ['-1', false], ['65536', false], ['1e3', false], [' 80', false], ['+80', false], ['٣٠٠٠', false]]) {
  const r = await run({ PORT: P, DATA_FILE: path.join(tmp, 'x.json') }, tmp);
  check(`PORT=${P} exits 1`, r.code === 1 && r.out === '' && r.err.trim().split('\n').length === 1, r);
  if (r.p) r.p.kill();
}
{
  const blocker = net.createServer().listen(0, '127.0.0.1');
  await new Promise((r) => blocker.on('listening', r));
  const bp = blocker.address().port;
  const r = await run({ PORT: String(bp), DATA_FILE: path.join(tmp, 'x.json') }, tmp);
  check('port in use exits 1', r.code === 1 && r.out === '', r);
  if (r.p) r.p.kill();
  blocker.close();
}
// PORT order: invalid port + bad data -> port error
{
  fs.writeFileSync(path.join(tmp, 'bad.json'), 'nope');
  const r = await run({ PORT: 'x', DATA_FILE: 'bad.json' }, tmp);
  check('PORT checked before data', r.code === 1 && !r.err.includes('cannot read data file'), r);
}
for (const [name, content] of [['empty.json', ''], ['bad.json', 'nope'], ['arr.json', '[]'], ['null.json', 'null'], ['bom.json', '﻿{"nextId":1,"bookings":[]}']]) {
  if (!fs.existsSync(path.join(tmp, name)) || name !== 'bad.json') fs.writeFileSync(path.join(tmp, name), content);
  const r = await run({ PORT: '0', DATA_FILE: name }, tmp);
  check(`data ${name} rejected`, r.code === 1 && r.err === `cannot read data file ${name}\n` && r.out === '', r);
  if (r.p) r.p.kill();
}
{
  fs.mkdirSync(path.join(tmp, 'dir'), { recursive: true });
  const r = await run({ PORT: '0', DATA_FILE: 'dir' }, tmp);
  check('data dir rejected', r.code === 1 && r.err === 'cannot read data file dir\n', r);
  if (r.p) r.p.kill();
}
{
  const r = await run({ PORT: '0', DATA_FILE: '' }, tmp);
  check('default data file ok', r.running && /^listening on http:\/\/127\.0\.0\.1:\d+\n$/.test(r.out), r);
  check('no file created at startup', !fs.existsSync(path.join(tmp, 'bookings.json')), '');
  r.p?.kill();
}

// main server
const dataRel = 'main.json';
let s = await run({ PORT: '0', DATA_FILE: dataRel }, tmp);
let port = Number(s.out.match(/:(\d+)\n/)[1]);
let r;
r = await req(port, 'GET', '/api/rooms');
check('rooms', r.status === 200 && JSON.stringify(r.json) === '{"rooms":["Aurora","Borealis","Cosmos"]}' && /content-type: application\/json; charset=utf-8/i.test(r.head), r);
for (const p of ['/api/%62ookings', '/api/./rooms', '/API/rooms', '/api/bookings/', '/api/bookings/1/', '/nope', '/index.html', '//api/rooms']) {
  r = await req(port, 'GET', p);
  check(`404 ${p}`, r.status === 404 && r.json?.error === 'not found', r.status);
}
for (const [m, p] of [['HEAD', '/api/rooms'], ['OPTIONS', '/api/bookings'], ['GET', '/api/bookings/abc'], ['PUT', '/api/bookings'], ['POST', '/'], ['DELETE', '/app.js'], ['PATCH', '/api/bookings/1']]) {
  r = await req(port, m, p);
  check(`405 ${m} ${p}`, r.status === 405 && (m === 'HEAD' || r.json?.error === 'method not allowed'), r.status);
}
r = await req(port, 'GET', '/');
check('page html', r.status === 200 && /text\/html; charset=utf-8/i.test(r.head), r.head);
r = await req(port, 'GET', '/app.js?x=1');
check('app.js', r.status === 200 && /text\/javascript; charset=utf-8/i.test(r.head), r.head);

// POST rules
const cases = [
  [{}, bk(), 415, 'content type must be application/json'],
  [{ 'Content-Type': 'text/plain' }, bk(), 415],
  [{ 'Content-Type': ' \tAPPLICATION/Json \t; charset=utf-8' }, bk({ date: '2026-01-01' }), 201],
  [{ 'Content-Type': 'application/json+x' }, bk(), 415],
  [J, 'x'.repeat(10001), 413, 'body too large'],
  [{ 'Content-Type': 'text/plain' }, 'x'.repeat(20001), 415],
  [J, '', 400, 'body must be a JSON object'],
  [J, 'null', 400], [J, '[]', 400], [J, '"s"', 400], [J, '1', 400], [J, 'true', 400],
  [J, '﻿' + bk(), 400],
  [J, bk({ room: 'aurora' }), 400, 'room must be one of Aurora, Borealis, Cosmos'],
  [J, '{"__proto__":{"room":"Aurora"},"title":"t","date":"2026-11-03","start":"09:00","end":"10:00"}', 400, 'room must be one of Aurora, Borealis, Cosmos'],
  [J, bk({ title: '   ' }), 400, 'title must be 1 to 80 characters'],
  [J, bk({ title: 'a'.repeat(81) }), 400],
  [J, bk({ title: 5 }), 400],
  [J, bk({ date: '2026-02-29' }), 400, 'date must be a valid YYYY-MM-DD date'],
  [J, bk({ date: '2100-01-01' }), 400], [J, bk({ date: '1999-12-31' }), 400], [J, bk({ date: ' 2026-11-03' }), 400], [J, bk({ date: '2026-11-3' }), 400],
  [J, bk({ date: '2026-04-31' }), 400], [J, bk({ date: '٢٠٢٦-11-03' }), 400],
  [J, bk({ start: '9:00' }), 400, 'start must be HH:MM'], [J, bk({ start: '24:00' }), 400],
  [J, bk({ end: '10:60' }), 400, 'end must be HH:MM'],
  [J, bk({ end: '09:00' }), 400, 'end must be after start'],
  [J, bk({ title: '  Standup  ', date: '2024-02-29', extra: 1 }), 201],
  [J, bk({ room: 'Borealis', start: '09:00', end: '10:00' }), 201],
  [J, bk({ room: 'Borealis', start: '10:00', end: '11:00' }), 201],
  [J, bk({ room: 'Borealis', start: '11:00', end: '12:00' }), 201],
  [J, bk({ room: 'Borealis', start: '09:30', end: '11:30' }), 409, 'room is already booked from 09:00 to 10:00'],
  [J, bk({ room: 'Borealis', start: '10:30', end: '11:30' }), 409, 'room is already booked from 10:00 to 11:00'],
];
for (const [h, b, st, msg] of cases) {
  r = await req(port, 'POST', '/api/bookings', { headers: h, body: b });
  check(`POST ${st} ${String(b).slice(0, 60)} ${JSON.stringify(h)}`, r.status === st && (!msg || r.json?.error === msg) && (st !== 201 || Object.keys(r.json).length === 6), [r.status, r.body.slice(0, 100)]);
}
// invalid utf8 in title
