    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    const t = setTimeout(() => resolve({ p, out, err, code: null, running: true }), 1500);
    p.on('exit', (code) => { clearTimeout(t); resolve({ out, err, code, running: false }); });
